#include "cuda_solver61.cuh"
la::BackendInput input(const la::Workload& w){return {1,8,unsigned(w.h.nodes),unsigned(w.h.jobs),unsigned(w.h.cells),unsigned(w.h.costs),w.h.edges,w.row.data(),w.node.data(),w.edge.data(),w.cost.data(),w.job.data(),w.cell.data()};}
template<class N,class E>int run(const la::Workload& w,unsigned shift,unsigned repeats,const char* reference,const char* output_path,const N* nodes,const E* edges,const char* repr,double load,double conversion,bool profile){
 auto in=input(w);CudaSession61<N,E> s(in,shift,nodes,edges,profile);std::vector<la::Cost> ref(w.golden.size()),out;std::ifstream f(reference,std::ios::binary);la::read(f,ref.data(),ref.size());
 for(unsigned r=0;r<=repeats;++r){out=s.solve();bool equal=!memcmp(out.data(),ref.data(),out.size()*8);std::cout<<std::setprecision(12)<<"{\"kind\":\"batch\",\"backend\":\"cuda61\",\"representation\":\""<<repr<<"\",\"shift\":"<<shift<<",\"repeat\":"<<r<<",\"E1_s\":"<<s.E1_wall_s<<",\"resident_s\":"<<s.resident_s<<",\"readback_s\":"<<s.readback_s<<",\"load_s\":"<<load<<",\"prepare_s\":"<<s.prepare_s+conversion<<",\"conversion_s\":"<<conversion<<",\"device_bytes\":"<<s.bytes<<",\"waves_batch\":"<<s.waves<<",\"cpp_match\":"<<(equal?"true":"false")<<",\"instrumented\":"<<(profile?"true":"false")<<",\"phases\":{";bool first=true;for(auto kv:s.phase.times){if(!first)std::cout<<',';first=false;std::cout<<'"'<<kv.first<<"\":"<<kv.second;}std::cout<<"}}\n"<<std::flush;if(!equal)return 3;}
 std::ofstream out_file(output_path,std::ios::binary);la::write(out_file,out.data(),out.size());return 0;
}
int main(int argc,char** argv){try{if(argc!=8)throw std::runtime_error("cuda61 workload shift repeats reference output original|compact profile");auto start=Clock::now();la::Workload w(argv[1]);double load=seconds(start);unsigned shift=std::stoul(argv[2]),repeats=std::stoul(argv[3]);bool profile=std::stoi(argv[7]);std::string repr=argv[6];if(repr=="original")return run(w,shift,repeats,argv[4],argv[5],w.node.data(),w.edge.data(),argv[6],load,0,profile);if(repr!="compact")throw std::runtime_error("bad representation");start=Clock::now();la61::Compact c(w);double conversion=seconds(start);return run(w,shift,repeats,argv[4],argv[5],c.node.data.data(),c.edge.data.data(),argv[6],load,conversion,profile);}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 10;}}
